function getUrl() {
    try {
        let urls = [];
        let html = java.ajax("https://8xsk.top");
        java.log("发布页响应长度: " + html.length);
        if (html.length < 100) throw new Error("响应异常，可能被反爬");

        let doc = org.jsoup.Jsoup.parse(html);
        let elements = doc.select("a[href]");
        java.log("页面链接总数: " + elements.size());

        let arr = elements.toArray();
        for (let i = 0; i < arr.length; i++) {
            let href = arr[i].attr("href");
            if (href == null) continue;
            href = href.trim();
            while (href.endsWith("/")) {
                href = href.substring(0, href.length - 1);
            }
            if (/^https?:\/\/[^\/]+$/.test(href) && !href.includes("8xsk.top")) {
                if (href.startsWith("http://")) {
                    href = "https://" + href.substring(7);
                }
                urls.push(href);
            }
        }

        urls = Array.from(new Set(urls));
        java.log("提取到的站源: " + urls.join("\n"));
        if (urls.length === 0) throw new Error("未获取到站源");

        let data = JSON.parse(source.getVariable());
        data.Urls = urls;
        source.setVariable(JSON.stringify(data, null, "\t"));
        java.toast(`获取到${urls.length}个站源\n${urls.join('\n')}`);
    } catch (e) {
        java.log("获取站源失败: " + e.message);
        java.toast("获取失败: " + e.message);
    }
}

function setUrl(n) {
    let data = JSON.parse(source.getVariable());
    if (n + 1 > data.Urls.length) return java.toast(`暂时没有站源${n + 1}`);

    let target = data.Urls[n];
    let timeNow = Date.now();

    try {
        let html = java.ajax(target);
        if (html.indexOf("八叉书库") == -1 && html.indexOf("bcshuku") == -1 && html.indexOf("最新章节") == -1) {
            throw new Error("站点内容不匹配");
        }
    } catch (e) {
        java.log(e);
        java.toast(`\n当前站源：${target}\n当前站源已失效，请检查网络或切换至其他站源!`);
        return;
    }

    let testTime = ((Date.now() - timeNow) / 1000).toFixed(2);
    data.sourceurl = target;
    source.setVariable(JSON.stringify(data, null, "\t"));
    java.toast(`当前站源已切换到：\n${target}\n🔻解析时间：${testTime}🔻`);
}

